//! Static compiled completion specs embedded into the binary.
//!
//! Generated by `build.rs` from `resources/specs/*.toml`.

include!(concat!(env!("OUT_DIR"), "/compiled_specs.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_compiled_specs_loaded() {
        assert!(COMPILED_SPECS.len() >= 25);
        let git_spec = find_compiled_spec("git").expect("git spec must exist");
        assert_eq!(git_spec.name, "git");
        assert!(git_spec.find_subcommand("checkout").is_some());

        let cargo_spec = find_compiled_spec("cargo").expect("cargo spec must exist");
        assert_eq!(cargo_spec.name, "cargo");
        assert!(cargo_spec.find_subcommand("build").is_some());
    }

    #[test]
    fn test_compiled_specs_size_budget() {
        // Size budget: compiled specs table in memory <= 150 KiB.
        // Let's measure the size of the static tables.
        let mut total_bytes = std::mem::size_of_val(COMPILED_SPECS);
        for cmd in COMPILED_SPECS {
            total_bytes += std::mem::size_of::<StaticCommandSpec>();
            total_bytes += cmd.name.len();
            total_bytes += cmd.description.len();
            for sub in cmd.subcommands {
                total_bytes += std::mem::size_of::<StaticSubcommandSpec>();
                total_bytes += sub.name.len();
                total_bytes += sub.description.len();
            }
            for opt in cmd.options {
                total_bytes += std::mem::size_of::<StaticOptionSpec>();
                total_bytes += opt.description.len();
            }
        }
        assert!(
            total_bytes <= 150 * 1024,
            "Total static spec memory: {} B > 150 KiB",
            total_bytes
        );
    }
}
